package com.hkdn.backend.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="actor_id") private User actor; @Column(nullable=false) private String action; @Column(name="entity_type",nullable=false) private String entityType; @Column(name="entity_id") private String entityId; @Column(columnDefinition="text") private String details; @Column(name="ip_address") private String ipAddress; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void prePersist(){createdAt=Instant.now();} public void setActor(User v){actor=v;}public void setAction(String v){action=v;}public void setEntityType(String v){entityType=v;}public void setEntityId(String v){entityId=v;}public void setDetails(String v){details=v;}public void setIpAddress(String v){ipAddress=v;} }
